import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BDCokyix.js";const b=JSON.parse('{"title":"UI Revamp v0 — Editor Surface References","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/prd/ui-revamp-v0-refs-editor.md","filePath":"architecture/prd/ui-revamp-v0-refs-editor.md","lastUpdated":1780254295000}'),n={name:"architecture/prd/ui-revamp-v0-refs-editor.md"};function s(i,e,l,d,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="ui-revamp-v0-—-editor-surface-references" tabindex="-1">UI Revamp v0 — Editor Surface References <a class="header-anchor" href="#ui-revamp-v0-—-editor-surface-references" aria-label="Permalink to &quot;UI Revamp v0 — Editor Surface References&quot;">​</a></h1><p>Companion to <a href="./ui-revamp-v0">ui-revamp-v0.md</a> and second pass after <a href="./ui-revamp-v0-refs">ui-revamp-v0-refs.md</a>. The first refs doc covered shell-level surfaces (3-pane, right-area panels, mention picker, bot-add flow, backend switcher). This one covers what happens <strong>inside the document</strong> — the surfaces the PRD §5 kill list flags (&quot;the current floating editor menu&quot;) and the §6 component plan lists as new (<code>SlashMenu</code>, <code>SelectionBubble</code>).</p><p>Same rules as the first refs doc: this is a kit of references for the lock pass, not a design. The PRD constraints carry over — 14px base, dense, no global shadows, 1px borders, <code>rounded-md</code> ceiling.</p><h2 id="_1-slash-menu-prd-§6-slashmenu" tabindex="-1">1. Slash menu (PRD §6 <code>SlashMenu</code>) <a class="header-anchor" href="#_1-slash-menu-prd-§6-slashmenu" aria-label="Permalink to &quot;1. Slash menu (PRD §6 `SlashMenu`)&quot;">​</a></h2><p>Inserts a block at the caret when the user types <code>/</code>. Needs to cover headings, lists, code, task, callout, divider, table, image, embed, plus our extensions (AI prompt, bot mention, link-to-doc).</p><h3 id="borrow" tabindex="-1">Borrow <a class="header-anchor" href="#borrow" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Craft — block context popover</strong> (<a href="https://refero.design/pages/c59f0e28-9eda-4861-a477-5992a2af2b92" target="_blank" rel="noreferrer">screen c59f0e28</a>). Not strictly a slash menu, but the <strong>payload shape</strong> is exactly what we want: a single column of rows, each row = a small monochrome icon + an action label, with one <strong>mid-emphasis row</strong> (&quot;Turn into Card&quot;) highlighted via a fill tint, dividers between semantic groups, and shortcut hints reserved for the right edge. No descriptions, no thumbnails — the row is the affordance. This is the density we need.</li><li><strong>Craft — shortcuts cheatsheet</strong> (<a href="https://refero.design/pages/f6f77988-1ac7-4644-bc66-242b40fcdf1a" target="_blank" rel="noreferrer">screen f6f77988</a>). Useful as a <strong>taxonomy reference</strong> for slash items, not as visual lock: four columns (Style / Navigate / Organize / Task) with keyboard-shortcut chips. Tells us how Craft groups block-related actions; our slash menu&#39;s section order should mirror that mental model (Text → List → Embed → Action → Advanced), because users coming from Notion/Craft already know it.</li><li><strong>Resend — left vertical block rail</strong> (<a href="https://refero.design/pages/811edb3c-d172-4add-bfce-ce8f5edb25e6" target="_blank" rel="noreferrer">screen 811edb3c</a>). A 4-icon vertical strip (<code>T</code>, image, 2x2 grid, sparkle) floats just outside the content column. This is a <strong>complement</strong> to the slash menu, not a replacement — the rail is the &quot;I don&#39;t remember the slash command&quot; affordance and lives in the gutter. Same items as the slash menu, surfaced differently. Worth adopting as a peripheral option for mouse users; keyboard users hit <code>/</code>.</li><li><strong>Search-as-you-type filtering.</strong> Across every editor we surveyed (Craft, Slab, Notion-likes), the slash menu uses a substring match on the row&#39;s label <em>and</em> alias list (e.g. <code>/h1</code> matches &quot;Heading 1&quot;). Important: filter narrows the <strong>same</strong> flat list and re-groups; do not collapse sections to &quot;best match&quot; — the user types <code>/co</code> and needs to see both <code>Code</code> and <code>Callout</code> so they can disambiguate with one more keystroke.</li></ul><h3 id="avoid" tabindex="-1">Avoid <a class="header-anchor" href="#avoid" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li><strong>Notion-style descriptions under each item.</strong> Common in marketing screenshots — a two-line row with &quot;Heading 1 / Big section heading&quot;. At 14px base this doubles the menu height for no information gain to repeat users. Use a single line with the label and a right-aligned shortcut hint instead.</li><li><strong>Thumbnails / previews for every block type.</strong> Tome and Glorify lean on tile previews (<a href="https://refero.design/pages/785ab890-8447-4414-8873-d85ab7b907a8" target="_blank" rel="noreferrer">Glorify 785ab890</a>). They make sense for design-canvas tools where blocks are visual. For prose blocks (heading, list, code, callout) a thumbnail is wasted pixels. Reserve previews for the embed sub-menu only (image, video, link card).</li><li><strong>A modal/centered command palette.</strong> Some apps (Luma 12ebb274, Deezer 7a916f34) center a search modal on dimmed canvas. Wrong for a slash menu — it has to anchor at the caret so the user&#39;s eye doesn&#39;t move. Popover, not modal.</li><li><strong>Sticky &quot;AI&quot; tile at the top.</strong> It&#39;s tempting (and Anthropic-friendly) but biases every slash interaction toward the LLM. Our LLM lives in the right-area chat panel (§4.5); the slash menu&#39;s job is block insertion. AI actions belong in the selection bubble&#39;s &quot;More&quot; menu and as a regular slash row (<code>/ask</code>).</li></ul><h2 id="_2-selection-bubble-prd-§6-selectionbubble" tabindex="-1">2. Selection bubble (PRD §6 <code>SelectionBubble</code>) <a class="header-anchor" href="#_2-selection-bubble-prd-§6-selectionbubble" aria-label="Permalink to &quot;2. Selection bubble (PRD §6 `SelectionBubble`)&quot;">​</a></h2><p>Floats above selected text. Replaces the &quot;ugly current floating menu&quot; called out in §5.</p><h3 id="borrow-1" tabindex="-1">Borrow <a class="header-anchor" href="#borrow-1" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Slab — single-row bubble</strong> (<a href="https://refero.design/pages/912347ff-08c8-44be-984a-a980e45fb641" target="_blank" rel="noreferrer">screen 912347ff</a>). The closest reference to what we want. Top-anchored above the selection, single dark pill, contents in left-to-right order: <code>Normal text ▾</code> (block-style dropdown) · <code>B</code> · <code>i</code> · <code>U</code> · <code>S</code> · <code>&lt;/&gt;</code> (code) · <code>link</code> · <code>highlight ▾</code> · <code>comment</code> · <code>⋯</code>. The block-style dropdown is the trick that lets a single row handle both <strong>inline</strong> (B/i/U) and <strong>block</strong> (Heading / Quote / Bullet) actions without spawning a second row. Lock this structure. Approx 8 icons + 1 dropdown + 1 overflow = the maximum that stays readable at 14px.</li><li><strong>Medium — minimal dual-purpose bubble</strong> (<a href="https://refero.design/pages/22dce083-1764-4dee-aea5-815b6f0106b8" target="_blank" rel="noreferrer">screen 22dce083</a>). Worth noting for the <strong>arrow-down tail</strong> on the bubble (a small triangle pointing at the selection). Adds 4px of height for clear anchoring; we should keep this since at our density a borderless floating pill can read as detached. Medium&#39;s content is too sparse (<code>B i | T T | &quot; 1≡ | 💬</code>) — they omit underline/strike entirely, which we cannot.</li><li><strong>Resend — bottom selection bar</strong> (<a href="https://refero.design/pages/811edb3c-d172-4add-bfce-ce8f5edb25e6" target="_blank" rel="noreferrer">screen 811edb3c</a>). Has the densest treatment of typography controls we found: <code>Text ▾ &lt;/&gt; B I U S &lt;/&gt; AB ≣ ≣ ≣ ≣</code>. Bottom-anchored rather than top-anchored, but the <strong>chip-style grouping</strong> (block-style chip on the left, divider, inline marks in the middle, divider, alignment on the right) is the right pattern for visually parsing many controls at a glance. Adopt the dividers.</li><li><strong>Wandb — small inline popover near tool icon</strong> (<a href="https://refero.design/pages/14943dab-2d00-4deb-9e8f-5d0446f2c5e4" target="_blank" rel="noreferrer">screen 14943dab</a>). Shows the <strong>link-insert pattern</strong> done well: clicking the link icon swaps the bubble&#39;s content area for a single text input with auto-paste + Enter to confirm, no second modal. That swap-in-place is what we want — not a second popover layered on top.</li></ul><h3 id="avoid-1" tabindex="-1">Avoid <a class="header-anchor" href="#avoid-1" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li><strong>Two-row bubbles by default.</strong> Notion classic exposes block-style as a separate top row. At our base size this becomes a 60px-tall floating shape, occluding the line above. Use Slab&#39;s single-row pattern with a dropdown for block-style.</li><li><strong>A floating &quot;More&quot; button that opens a wide menu.</strong> It moves the eye twice (bubble → menu) and the menu often overlaps the bubble. Instead: <code>⋯</code> opens a small column <strong>anchored to the bubble&#39;s right edge</strong>, containing color, clear-formatting, AI-rewrite, comment-thread — the long tail of low-frequency actions. Keep the bubble itself stable; only the overflow moves.</li><li><strong>Inline link previews inside the bubble.</strong> Some editors show the link target&#39;s OG image as soon as you paste — at our density it shoves the bubble to 2 rows. Show the parsed URL as plain monospace text in the bubble&#39;s link-input mode; previews belong on the inserted link block, not the editing chrome.</li></ul><h2 id="_3-block-menus-drag-handles-prd-§3-dense-default" tabindex="-1">3. Block menus + drag handles (PRD §3 dense default) <a class="header-anchor" href="#_3-block-menus-drag-handles-prd-§3-dense-default" aria-label="Permalink to &quot;3. Block menus + drag handles (PRD §3 dense default)&quot;">​</a></h2><p>The &quot;row hover&quot; affordance: on <code>mouseenter</code> of a block, show <code>⋮⋮</code> drag handle and <code>+</code> insert button in the <strong>left gutter</strong> outside the content column. Click the handle (or right-click anywhere on the block) → per-block menu.</p><h3 id="borrow-2" tabindex="-1">Borrow <a class="header-anchor" href="#borrow-2" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Craft — per-block context menu</strong> (<a href="https://refero.design/pages/c59f0e28-9eda-4861-a477-5992a2af2b92" target="_blank" rel="noreferrer">screen c59f0e28</a>). The reference. Action list, top to bottom: <code>Add Content / Add Reaction / Add Comment / Turn into Card / Open Assistant / Remind Me ▸ / Insert Block Above / Insert Block Below / Copy Link to Block / Delete</code>. Notable: <strong>Turn into Card</strong> is the only action with a colored fill — the destructive <code>Delete</code> is plain text at the bottom, which is correct (destructive is not the same as emphasis). The submenu marker <code>▸</code> on &quot;Remind Me&quot; gives us the pattern for nested actions (we&#39;ll use it for <code>Turn into ▸</code> → list of block types, and <code>Color ▸</code> → swatches).</li><li><strong>Craft — right-side Insert/Format/Style/Info panel</strong> (<a href="https://refero.design/pages/c59f0e28-9eda-4861-a477-5992a2af2b92" target="_blank" rel="noreferrer">same screen</a>). A more permanent palette pinned to the right of the editor. <strong>Reject</strong> as a default surface (it competes with our right-area panel stack) but note the affordance: when a block is selected, the right-area can host a contextual <strong>Block</strong> panel (replacing the page-tree popover) for users who prefer a persistent inspector over hover affordances. Future v0.1.</li><li><strong>Gutter <code>⋮⋮ +</code>, not in-content.</strong> Across Notion-likes the drag handle never overlays the text — it lives in the left gutter, becomes visible on row hover, and the cursor stays on the text. We honor this: gutter width budget is ~24px, two stacked 16px icons, no labels.</li><li><strong>Right-click parity.</strong> The same per-block menu opens on right-click anywhere in the row. This is critical for trackpad users who never hover-discover the handle. Lock both entry points.</li></ul><h3 id="avoid-2" tabindex="-1">Avoid <a class="header-anchor" href="#avoid-2" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li><strong>Persistent visible drag handles.</strong> Mailchimp (<a href="https://refero.design/pages/08af2456-a1f9-4d7c-804b-3ae6e137dd2e" target="_blank" rel="noreferrer">08af2456</a>) and many email builders show a permanent drag chrome around every block. Looks busy and prevents the editor from feeling like prose. Hover-only.</li><li><strong>Hamburger menus per block.</strong> Some editors use a <code>⋯</code> instead of <code>⋮⋮</code>, which conflates &quot;drag me&quot; with &quot;open menu&quot;. Use <code>⋮⋮</code> strictly for drag (cursor: grab) and <code>+</code> strictly for insert-below; right-click is the menu entry.</li><li><strong>A &quot;Turn into&quot; picker that opens a modal.</strong> It interrupts flow. Use a flyout submenu off the per-block menu — same shape as the slash menu&#39;s block-type rows, so users learn one list.</li></ul><h2 id="_4-code-blocks-and-embeds-prd-§6-—-slashmenu-outputs" tabindex="-1">4. Code blocks and embeds (PRD §6 — <code>SlashMenu</code> outputs) <a class="header-anchor" href="#_4-code-blocks-and-embeds-prd-§6-—-slashmenu-outputs" aria-label="Permalink to &quot;4. Code blocks and embeds (PRD §6 — `SlashMenu` outputs)&quot;">​</a></h2><h3 id="borrow-3" tabindex="-1">Borrow <a class="header-anchor" href="#borrow-3" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Anthropic Workbench — &quot;Code for Claude API&quot; modal</strong> (<a href="https://refero.design/pages/983dbb9e-1a8e-4373-94f7-4465c9249aca" target="_blank" rel="noreferrer">screen 983dbb9e</a>). The cleanest in-doc code-block chrome we found. Top strip: <code>Python ▾</code> on the left (the language picker), <code>Copy Code</code> + <code>View Docs</code> on the right. Code body has line numbers in a muted left column, syntax-highlighted body, no shadow, just a 1px border + slight bg shift. <strong>Lock this header layout</strong> for inline code blocks: <code>&lt;language-pill&gt;</code> left, <code>&lt;copy&gt;</code> right, nothing else on first render. The &quot;Run&quot; action — when we add it for executable blocks — joins the right cluster as a third button, not a separate row.</li><li><strong>Linear developer docs</strong> (<a href="https://refero.design/pages/cbbd2bc8-9bc9-4cdd-ba74-00484914bddf" target="_blank" rel="noreferrer">screen cbbd2bc8</a>). Useful for the <strong>language pill</strong> styling: small monospace label inside a low-contrast pill, no chevron when there&#39;s only one language. Our pill always shows the chevron because every code block can be re-languaged.</li><li><strong>Resend image-block chrome</strong> (<a href="https://refero.design/pages/eff09bc8-6e14-42bf-9591-ca7630ec1234" target="_blank" rel="noreferrer">screen eff09bc8</a>). Image embed renders edge-to-edge inside the content column with a thin border, a centered hover handle (drag/resize), and a small caption row below the image (italic, muted). No floating action bar over the image itself. We adopt: <strong>embed chrome is the caption row + a hover-revealed <code>⋯</code> in the top-right corner of the embed</strong>, not a persistent toolbar.</li><li><strong>Mercury attachment card</strong> (<a href="https://refero.design/pages/018f4d0f-47e5-4c3e-8833-4b78650960d7" target="_blank" rel="noreferrer">screen 018f4d0f</a>). For file embeds: thin horizontal card with a left mime-type icon, filename + size middle, download icon on the right. One row, ~36px tall. This is what a non-previewable file (zip, dmg, binary) should render as inline. Distinct from image/video which gets full-bleed.</li></ul><h3 id="synthesis-embed-chrome-rules" tabindex="-1">Synthesis: embed chrome rules <a class="header-anchor" href="#synthesis-embed-chrome-rules" aria-label="Permalink to &quot;Synthesis: embed chrome rules&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Embed type</th><th>Chrome</th><th>Notes</th></tr></thead><tbody><tr><td>Code block</td><td>Header strip: <code>&lt;lang ▾&gt;</code> left, <code>&lt;copy&gt;</code> right. Border + bg, no shadow.</td><td>Run button added later for executable kinds.</td></tr><tr><td>Image / Video</td><td>Full-bleed inside content column. Caption row below. Hover-<code>⋯</code> top-right for menu (alt text, replace, download, delete).</td><td>No persistent toolbar on the asset itself.</td></tr><tr><td>File (non-previewable)</td><td>Single-row card: icon · filename · size · download.</td><td>Mime-detected from content (PRD §4.9).</td></tr><tr><td>Link card (URL embed)</td><td>Card: site favicon, title, 1-line description, URL slug. Border, no shadow.</td><td>If unfurl fails, fall back to plain underlined link, not an error card.</td></tr><tr><td>Failed embed</td><td>Inline 1-row warning row, retry action on the right. <strong>Not</strong> a centered modal, not a toast.</td><td>Editing the URL stays in place.</td></tr></tbody></table><h3 id="avoid-3" tabindex="-1">Avoid <a class="header-anchor" href="#avoid-3" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li><strong>Lightbox / modal preview for inline images.</strong> Multiple references do this (<a href="https://refero.design/pages/3370d540-828e-414f-915d-70a180e9f7b5" target="_blank" rel="noreferrer">Clipchamp 3370d540</a>, <a href="https://refero.design/pages/bf8cf417-4bd6-4cb7-b558-106c915d7de5" target="_blank" rel="noreferrer">Rox bf8cf417</a>) — fine for a gallery, wrong inside a document. Click on an inline image edits its properties; nothing should fullscreen.</li><li><strong>A floating language picker inside the code body.</strong> Some references float it over the code top-right (overlapping code on long lines). Anchor it to the header strip.</li><li><strong>Copy buttons that show a green check toast.</strong> A 600ms inline label swap (&quot;Copy&quot; → &quot;Copied&quot;) inside the same button is denser and faster.</li><li><strong>Run-output panels stacked under every code block by default.</strong> Run is opt-in per block; the output area appears only after a run, collapses by default after the user reads it.</li></ul><h2 id="_5-pattern-locks-recommendations-for-adr-0005" tabindex="-1">5. Pattern locks (recommendations for ADR-0005) <a class="header-anchor" href="#_5-pattern-locks-recommendations-for-adr-0005" aria-label="Permalink to &quot;5. Pattern locks (recommendations for ADR-0005)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>PRD ref</th><th>Pattern locked from refs</th><th>Reference</th></tr></thead><tbody><tr><td>§6 <code>SlashMenu</code></td><td>Single-column popover anchored at caret. Rows = monochrome icon + label + right-aligned shortcut hint. Sections in fixed order (Text · List · Embed · Action · Advanced). Substring filter across labels + aliases. No descriptions, no thumbnails.</td><td>Craft c59f0e28 (row shape), Craft f6f77988 (taxonomy), Resend 811edb3c (peripheral rail)</td></tr><tr><td>§6 <code>SelectionBubble</code></td><td>Single-row dark pill above selection. Order: <code>&lt;block-style ▾&gt;</code> · B · i · U · S · <code>&lt;/&gt;</code> · link · highlight · comment · <code>⋯</code>. Dividers between block / inline / action clusters. Link icon swaps the row into a single-input link mode in place.</td><td>Slab 912347ff (lock), Medium 22dce083 (tail), Resend 811edb3c (dividers), Wandb 14943dab (link mode)</td></tr><tr><td>§3 row hover</td><td>Left-gutter <code>⋮⋮</code> drag handle + <code>+</code> insert-below, both 16px, gutter ~24px wide, hover-only. Right-click anywhere in the row opens the per-block menu. Drag and menu have distinct icons.</td><td>Craft c59f0e28</td></tr><tr><td>Per-block menu</td><td>Single column. Order: Add Content · Comment · Turn into ▸ · Color ▸ · Copy Link to Block · Insert Above · Insert Below · Duplicate · Delete. Submenus open as flyouts (<code>▸</code>), not modals.</td><td>Craft c59f0e28</td></tr><tr><td>Code block chrome</td><td>Top strip: <code>&lt;language ▾&gt;</code> left, <code>&lt;copy&gt;</code> right (Run later joins right cluster). Line numbers in muted left column. 1px border, no shadow. Inline &quot;Copied&quot; label swap, no toast.</td><td>Anthropic Workbench 983dbb9e, Linear cbbd2bc8</td></tr><tr><td>Image / video embed</td><td>Full-bleed inside content column, caption row below, hover-revealed <code>⋯</code> top-right for properties. No persistent toolbar over the asset.</td><td>Resend eff09bc8</td></tr><tr><td>File embed (non-previewable)</td><td>Single-row card: mime-icon · filename · size · download. ~36px tall.</td><td>Mercury 018f4d0f</td></tr><tr><td>Link card embed</td><td>Card: favicon · title · 1-line description · URL. Border, no shadow. Fall back to plain link if unfurl fails.</td><td>(cross-product convention)</td></tr><tr><td>Failed embed</td><td>Inline 1-row warning, retry on the right, edit URL in place. No modal, no toast.</td><td>(no good single ref; constraint follows from §3 density rules)</td></tr></tbody></table><h2 id="_6-open-follow-up" tabindex="-1">6. Open follow-up <a class="header-anchor" href="#_6-open-follow-up" aria-label="Permalink to &quot;6. Open follow-up&quot;">​</a></h2><ul><li><strong>Tables.</strong> Refero coverage of in-doc tables (not data-grid tools) was thin. We need to lock: column-resize affordance, per-cell context menu, header-row toggle, sortable vs static, and how tables collapse when the content column is narrow. Punt to a small follow-up pass; ship v0 with read-only-ish tables (insert / type / delete row, no column resize) and revisit.</li><li><strong>Math / equation block.</strong> Slab and Craft both support it as a slash item but neither shows the editor UI clearly in the refs we found. KaTeX-shaped input is the de-facto baseline; the only design decision is whether the rendered block sits inline (like code) or full-bleed (like an image). Tentatively: inline-block treatment, same chrome as code, language pill replaced by <code>LaTeX</code> static label.</li><li><strong>AI inline transform</strong> (&quot;rewrite this paragraph&quot;). The PRD keeps AI in the right-area chat, but the selection-bubble overflow has an AI action. We didn&#39;t lock how the streaming result lands back in the editor — diff-overlay in place? Insert-below-with-accept-reject? Defer to a dedicated AI-edit refs pass; do not ship in the first cut of <code>SelectionBubble</code>.</li><li><strong>Drag-to-reorder visuals.</strong> All refs hide the drop indicator until the drag is in flight; nobody shows a polished &quot;dropping here&quot; treatment we can copy. Plan: a 2px accent rule between blocks during drag, no spacer animation. Confirm in Storybook against the actual block heights before locking.</li><li><strong>Mobile / touch.</strong> Out of scope for v0 (no touch target in the product yet), but hover-only handles are a known accessibility risk on touch when we get there. Note for the next revamp.</li></ul><hr><p><em>Next pass after this lands: revise PRD §6 to reference the locked patterns by name; add a Storybook scaffold task per component (<code>SlashMenu</code>, <code>SelectionBubble</code>, plus the unbranded <code>BlockMenu</code> + <code>RowHoverHandles</code> that fall out of §3); then promote the §5 table above into ADR-0005 alongside the first refs doc&#39;s locks.</em></p>',34)])])}const g=t(n,[["render",s]]);export{b as __pageData,g as default};
